// Spiral Sunburst - a turning spiral tunnel of light with a hot center, over
// a dark haze sprinkled with flashing sparkles. Parametric (u,v), animated.
//
// HOW IT CLOSES
//  - Vortex: measured from the NEAREST copy of its center across the seams,
//    and faded out completely before the half-turn where that copy changes,
//    so it can sit anywhere, even on a seam. Its arms use whole multiples of
//    the angle, so they close around the center.
//  - Haze and sparkles: whole numbers of cells per turn, wrapped indices.
// Twisted gluing (Klein bottle, Moebius band): set MIRROR_V to 1.0.
// Dock colors: u_col1 = light of the vortex, u_col2 = deep tone and haze.

const float CENTER_U = 0.5;    // center of the vortex (turns along u)
const float CENTER_V = 0.5;    // center of the vortex (turns along v)
const float SIZE     = 0.42;   // radius of the vortex in turns         [0.1 .. 0.45]
const float ASPECT   = 1.0;    // >1 squeezes the vortex along u        [0.3 .. 3]
const float ARMS     = 5.0;    // spiral arms (whole number)            [1 .. 12]
const float TWIST    = 3.0;    // how tightly the arms wind             [0 .. 8]
const float RINGS    = 0.35;   // depth of the tunnel rings             [0.1 .. 1]
const float SPEED    = 1.0;    // animation speed (0 = still)
const float CORE     = 1.0;    // hot light at the center               [0 .. 2]
const float SPARKLE  = 0.8;    // flashing sparkles                     [0 .. 1.5]
const float DOTS     = 48.0;   // sparkle cells per turn (whole number) [12 .. 120]
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

// ---- seam-free toolkit: every grid has a whole number of cells per turn and
// ---- every cell index is wrapped, so the pattern repeats exactly at u, v = 0/1
vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);   // 0 -> 0.5 -> 0: equal at both ends
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

// random value of cell c, wrapped into the period n (negative indices too):
// the same cell one turn away gets the same value.
// NB: helper functions here return float/vecN only -- the per-mesh renamer of
// the engine recognizes those return types, not ivec2.
float cellHash(ivec2 c, ivec2 n, int salt) {
    ivec2 w = ivec2(mod(vec2(c), vec2(n)));
    uint h = uint(w.x) * 0x8da6b343u + uint(w.y) * 0xd8163841u + uint(salt) * 0xcb1ab31fu;
    h ^= h >> 15; h *= 0x2c1b3c6du;
    h ^= h >> 12; h *= 0x297a2d39u;
    h ^= h >> 15;
    return float(h >> 8) * (1.0 / 16777216.0);
}

vec2 cellHash2(ivec2 c, ivec2 n, int salt) {
    return vec2(cellHash(c, n, salt), cellHash(c, n, salt + 101));
}

// value noise with a period of n cells; uv in turns (0..1 = one turn)
float pnoise(vec2 uv, ivec2 n, int salt) {
    vec2 p = uv * vec2(n);
    ivec2 i = ivec2(floor(p));
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = cellHash(i, n, salt);
    float b = cellHash(i + ivec2(1, 0), n, salt);
    float c = cellHash(i + ivec2(0, 1), n, salt);
    float d = cellHash(i + ivec2(1, 1), n, salt);
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// fractal sum: each octave doubles the cells, so it stays periodic
float pfbm(vec2 uv, ivec2 n, int octaves, int salt) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int o = 0; o < 6; o++) {
        if (o >= octaves) break;
        sum += amp * pnoise(uv, n, salt + 17 * o);
        norm += amp;
        amp *= 0.5;
        n *= 2;
    }
    return sum / norm;
}

// Voronoi on a grid of n cells per turn (p in cells). Returns
//   x = distance to the nearest point, y = distance to the nearest border,
//   z = random id of the nearest cell.
// rel = p minus the nearest point; edgeDir = unit vector toward the nearest
// border (the downhill direction of anything that rises from the borders).
vec3 pvoronoi(vec2 p, ivec2 n, float jitter, int salt, out vec2 rel, out vec2 edgeDir) {
    ivec2 ip = ivec2(floor(p));
    vec2 fp = fract(p);
    float best = 1.0e9;
    ivec2 bestCell = ivec2(0);
    vec2 bestPt = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 g = ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 dv = pt - fp;
        float dd = dot(dv, dv);
        if (dd < best) { best = dd; bestCell = g; bestPt = pt; }
    }
    float border = 1.0e9;
    edgeDir = vec2(1.0, 0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        if (i == 0 && j == 0) continue;
        ivec2 g = bestCell + ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 ab = pt - bestPt;
        float lab = length(ab);
        if (lab < 1.0e-5) continue;
        vec2 dir = ab / lab;
        float dist = dot(0.5 * (bestPt + pt) - fp, dir);
        if (dist < border) { border = dist; edgeDir = dir; }
    }
    rel = fp - bestPt;
    return vec3(sqrt(best), border, cellHash(ip + bestCell, n, salt + 7));
}

// glow of a line where s crosses zero; fades to its mean value when the
// lines get closer than a pixel (dphase = phase change across one pixel)
float glowLine(float s, float width, float dphase) {
    float g = width / (s * s + width);
    float mean = sqrt(width / (1.0 + width));
    return mix(g, mean, smoothstep(0.6, 2.0, dphase));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 raw = fragCoord / iResolution.xy;
    vec2 uv = seamFold(raw);
    float time = iTime * SPEED;
    // pixel size in turns; fract(raw + 0.5) ignores the jump at the seam
    vec2 fw = min(fwidth(raw), fwidth(fract(raw + 0.5)));
    float px = max(fw.x * ASPECT, fw.y);

    // ---- haze
    float haze = pfbm(uv + vec2(0.01 * time, 0.0), ivec2(3), 4, 5);
    vec3 col = u_col2 * (0.12 + 0.4 * haze);

    // ---- vortex
    vec2 d0 = uv - vec2(CENTER_U, CENTER_V);
    d0 -= floor(d0 + 0.5);                          // nearest copy across the seams
    vec2 d = d0 * vec2(ASPECT, 1.0);
    float rho = max(length(d), 1.0e-4);             // distance in turns
    float r = rho / SIZE;                           // 1 = rim of the vortex
    float ang = atan(d.y, d.x);
    float reach = smoothstep(1.0, 0.7, r);

    // tunnel rings: depth ~ 1/r, flowing outward; wobbled by whole
    // multiples of the angle so they still close around the center
    float z = RINGS / r - 0.6 * time
            + 0.12 * sin(3.0 * ang + 1.7 * time) + 0.07 * sin(5.0 * ang - 1.1 * time);
    float rings = glowLine(sin(TAU * z), 0.08, TAU * RINGS * SIZE / (rho * rho) * px);

    // log spiral arms turning around the center
    float spiral = ARMS * ang + TWIST * log(r) - 0.8 * time;
    float arms = glowLine(sin(spiral), 0.12, sqrt(ARMS * ARMS + TWIST * TWIST) / rho * px);

    float throat = exp(-1.5 * r);
    float light = (0.55 * rings + 0.7 * arms * (0.4 + 0.6 * rings)) * (0.35 + 0.9 * throat);
    vec3 vortex = mix(u_col2, u_col1, clamp(light, 0.0, 1.0)) * light * 1.4;
    // warm light filling the throat of the tunnel
    vortex += mix(u_col2, u_col1, 0.6) * 0.45 * exp(-2.5 * r);
    vortex += CORE * exp(-r * r * 9.0) * mix(u_col1, vec3(1.0, 0.95, 0.85), 0.7) * 2.0;
    col += reach * vortex;

    // ---- sparkles: one per cell, each flashing at its own pace
    ivec2 nd = ivec2(int(DOTS));
    vec2 sp = uv * vec2(nd);
    ivec2 cell = ivec2(floor(sp));
    vec2 f = fract(sp) - 0.5;
    float h = cellHash(cell, nd, 3);
    float beat = sin(time * (1.5 + 4.0 * h) + TAU * cellHash(cell, nd, 4));
    float flash = smoothstep(0.9, 1.0, beat);
    float spot = exp(-dot(f, f) * 70.0);
    vec3 tint = 0.5 + 0.5 * cos(TAU * (h + vec3(0.0, 0.33, 0.67)));
    col += SPARKLE * flash * spot * mix(tint, vec3(1.0), 0.45) * 1.5;

    col = 1.0 - exp(-col * 1.4);
    fragColor = vec4(col, 1.0);
}
